function walk(dir) {
  const files = [];
  for (const name of readdirSync(dir)) {
    const path = join(dir, name);
    if (statSync(path).isDirectory()) files.push(...walk(path));
    else if (/\.(tsx|ts)$/.test(name)) files.push(path);
  }
  return files;
}

function productCopy(source) {
  return source
